147	/// Gather the facts about the binary at `bin`, after the build, and
148	/// about the trunk of the work repo at `root`.
149	pub fn gather(root: &Path, bin: &Path, dest: &Path) -> Result<Facts, String> {
150	    Ok(Facts {
151	        trunk: crate::jj::cid_of(root, TRUNK).ok(),
152	        trunk_origin: crate::jj::cid_of(root, &format!("{TRUNK}@origin")).ok(),
153	        version: manifest_version(root)?,
154	        stamp: read_stamp(&stamp_path(bin)),
155	        bin_id: BinaryId::of(bin).ok(),
156	        reported: run_version(bin).as_deref().and_then(parse_reported),
157	        dest_dir_exists: dest.parent().is_some_and(Path::is_dir),
158	    })
159	}
