161	/// `[install] dir` at `root`: `~` and `~/...` against the home
162	/// directory, any other relative value against the config file's
163	/// directory, an absolute one as is. Its absence is the workspace
164	/// having nothing to install.
165	pub fn install_dir(root: &Path) -> Result<PathBuf, String> {
166	    let cfg = crate::config_md::load(root)
167	        .map_err(|e| format!("install: {e}"))?
168	        .ok_or_else(|| format!("install: no config in '{}'", root.display()))?;
169	    let value = crate::toml_simple::toml_get(&cfg.map, "install.dir").ok_or_else(|| {
170	        format!(
171	            "install: {}: no `install.dir`, so this workspace has nothing to install. Name the \
172	             directory the release build is copied into, such as `~/.cargo/bin` (see `vc-x1 \
173	             config work`)",
174	            cfg.path.display()
175	        )
176	    })?;
177	    // OK: a loaded config's path is a file, so it has a parent
178	    let cfg_dir = cfg.path.parent().unwrap_or(root);
179	    expand_dir(cfg_dir, value, crate::jj::session::home_dir().as_deref())
180	}
