182	/// Expand an `[install] dir` value: `~` against `home`, else against
183	/// `cfg_dir` when relative.
184	fn expand_dir(cfg_dir: &Path, value: &str, home: Option<&Path>) -> Result<PathBuf, String> {
185	    let rest = if value == "~" {
186	        Some("")
187	    } else {
188	        value.strip_prefix("~/")
189	    };
190	    match rest {
191	        Some(rest) => home
192	            .map(|h| h.join(rest))
193	            .ok_or_else(|| format!("install: `install.dir` is '{value}' and HOME is not set")),
194	        None => Ok(crate::common::resolve_repo_path(cfg_dir, value)),
195	    }
196	}
