198	/// The manifest's version, `[package] version` in the `Cargo.toml` at
199	/// `root`.
200	pub fn manifest_version(root: &Path) -> Result<String, String> {
201	    let path = root.join("Cargo.toml");
202	    let map = crate::toml_simple::toml_load(&path)
203	        .map_err(|e| format!("install: cannot read '{}': {e}", path.display()))?;
204	    crate::toml_simple::toml_get(&map, "package.version")
205	        .cloned()
206	        .ok_or_else(|| format!("install: '{}' has no `[package] version`", path.display()))
207	}
