209	/// The stamp at `path` read back, `None` when there is none or it
210	/// names no commit.
211	pub fn read_stamp(path: &Path) -> Option<StampRecord> {
212	    let map = crate::toml_simple::toml_load(path).ok()?;
213	    let get = |k: &str| crate::toml_simple::toml_get(&map, k);
214	    let commit = get("commit")?.clone();
215	    let size = get("size").and_then(|v| v.parse().ok());
216	    let mtime_ns = get("mtime-ns").and_then(|v| v.parse().ok());
217	    let id = match (size, mtime_ns) {
218	        (Some(size), Some(mtime_ns)) => Some(BinaryId { size, mtime_ns }),
219	        _ => None,
220	    };
221	    Some(StampRecord {
222	        commit,
223	        state: get("state").and_then(|v| SourceState::parse(v)),
224	        id,
225	    })
226	}
