419	/// Run the release build, as `vc-x1 build` does, then report the
420	/// binary and copy it unless refused or a dry run. Cargo rebuilds only
421	/// what changed, so with nothing changed the binary already tested is
422	/// the one copied.
423	pub fn install(params: &InstallParams) -> Result<(), Box<dyn std::error::Error>> {
424	    debug!("install: entry params={params:?}");
425	    crate::build_cmd::build(&params.release)?;
426	    let facts = gather(&params.root, &params.bin, &params.dest)?;
427	    copy_reported(&params.bin, &params.dest, &facts, params.dry_run)
428	}
429	
430	/// Print the report, refuse with every reason at once when the copy
431	/// would be wrong, then copy `bin` to `dest` unless it is a dry run.
432	pub fn copy_reported(
433	    bin: &Path,
434	    dest: &Path,
435	    facts: &Facts,
436	    dry_run: bool,
437	) -> Result<(), Box<dyn std::error::Error>> {
438	    info!("install: '{}' -> '{}'", bin.display(), dest.display());
439	    for line in report(facts) {
440	        info!("install:   {line}");
441	    }
442	    let reasons = refusals(facts, bin, dest);
443	    if !reasons.is_empty() {
444	        let list: String = reasons.iter().map(|r| format!("\n  - {r}")).collect();
445	        return Err(format!(
446	            "install: refused, nothing copied to '{}':{list}",
447	            dest.display()
448	        )
449	        .into());
450	    }
451	    if dry_run {
452	        info!("install: [dry-run] copied nothing");
453	        return Ok(());
454	    }
455	    deploy(bin, dest)?;
456	    info!("install: copied");
457	    Ok(())
458	}
