228	/// Run `bin -V` and return what it prints, `None` when it cannot be
229	/// run or fails.
230	fn run_version(bin: &Path) -> Option<String> {
231	    // Register entry 7 (clippy.toml): install runs the release binary
232	    // itself, `-V` alone, to report the binary it is about to copy.
233	    #[allow(clippy::disallowed_methods)]
234	    let out = std::process::Command::new(bin).arg("-V").output().ok()?;
235	    if !out.status.success() {
236	        return None;
237	    }
238	    String::from_utf8(out.stdout).ok()
239	}
